export function SavedDashboard({
  name = "{{name}}",
  savedAt = "{{savedAt}}",
  shared = {{shared}},
  widgetCount = {{widgetCount}},
  color = "{{color}}",
}) {
  return (
    <article style={{ display: "flex", gap: 12, alignItems: "center", border: "1px solid #24143018", borderRadius: 10, padding: 12, font: "13px system-ui, sans-serif", color: "#241430", maxWidth: 320 }}>
      <div aria-hidden="true" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 3, width: 52, height: 38, borderRadius: 6, border: "1px solid #24143018", overflow: "hidden", flex: "none" }}>
        <span style={{ gridColumn: "span 2", background: color, opacity: 0.9 }} />
        <span style={{ background: color, opacity: 0.6 }} />
        <span style={{ background: color, opacity: 0.4 }} />
      </div>
      <div>
        <strong style={{ display: "block" }}>{name}</strong>
        <span style={{ display: "block", fontSize: 12, opacity: 0.7 }}>{widgetCount} widgets · Saved {savedAt}{shared ? " · Shared" : ""}</span>
      </div>
    </article>
  );
}
